(function(root){
'use strict';
const bundle=root.PLAnnotationsSample,model=root.PLAnnotationsModel.create(bundle),esc=MatchWorkspace.esc;
const reconstruction=root.PLReconstructionSample&&root.PLReconstructionModel?root.PLReconstructionModel.create(root.PLReconstructionSample,bundle):null;
const hasTimeline=!!(root.PLTimeline&&root.PLTimelineSample&&root.PLTimelineModel);
const hasGoal=!!(root.PLGoalPitch&&root.PLGoalSample&&root.PLGoalModel);
const hasPassage=!!(root.PLPassageView&&root.PLPassageSample&&root.PLPassageModel);
const hasReconstructed=!!(root.PLReconstructedView&&root.PLReconstructedModel&&root.PLReconstructedSample);
const hasOfficial=!!(root.PLOfficialView&&root.PLOfficialSample&&root.PLOfficialModel);
const panel=document.querySelector('#pl-workspace'),node=id=>panel.querySelector('#pl-'+id);
let mode=hasReconstructed?'reconstructed':hasGoal?'goal':hasTimeline?'timeline':reconstruction?'estimated':'reviewed',cursor=reconstruction?reconstruction.start:model.start,selected=reconstruction?reconstruction.participants[0].id:model.identities[0].id,timer=null,generation=0,opened=false,onBack=null,factKey='';
const states={reviewed:{cursor:model.start,selected:model.identities[0].id},estimated:reconstruction?{cursor:reconstruction.start,selected:reconstruction.participants[0].id}:null};
const estimated=()=>mode==='estimated',active=()=>estimated()?reconstruction:model,participants=()=>estimated()?reconstruction.participants:model.identities;
const now=()=>root.performance?.now?.()??Date.now();
const text=(el,value)=>{if(el.textContent!==value)el.textContent=value;};
const questions=['What has been observed?','Where is this player?','What does the scoreboard show?','What is missing here?'];
panel.innerHTML=`<div class="pl-heading"><div><div class="eyebrow">RECORDED MATCH</div><h1 id="pl-title" tabindex="-1">Brentford <em>v Chelsea</em></h1><p>18 September 2026 · Generated whole-match replay + separate video evidence · No live feed</p></div><button id="pl-back" class="text-button">← Back to the season</button></div><div class="pl-mode-switch" id="pl-modes" role="group" aria-label="Replay evidence mode" ${reconstruction?'':'hidden'}><button id="pl-mode-estimated" aria-pressed="true">Estimated replay</button><button id="pl-mode-reviewed" aria-pressed="false">Reviewed captures</button></div><section id="pl-inspector" class="pl-inspector" aria-label="Inspect recorded annotations"><div id="pl-context"></div><div id="pl-reviewed-map"><div class="pl-region-heading"><h2>Schematic region</h2><span>Side and exact location unknown</span></div><div class="pl-zone-map" role="img" id="pl-diagram" aria-label="No supported coarse position"><div id="pl-goalmouth" class="pl-region" data-active="false"><span class="pl-region-shape goalmouth" aria-hidden="true"></span><strong>Goalmouth region</strong><small>Not a coordinate or player position</small></div><div id="pl-corner" class="pl-region" data-active="false"><span class="pl-region-shape corner" aria-hidden="true"></span><strong>Corner boundary</strong><small>Pitch side unknown</small></div></div></div><section id="pl-estimated-map" hidden aria-label="Schematic estimated pitch positions"><div class="pl-region-heading"><h2>Estimated positions</h2><span>Attacking half · schematic</span></div><div class="pl-reconstruction-pitch"><div class="pl-reconstruction-field" id="pl-reconstruction-field" role="group" aria-label="Schematic attacking half. Goal at left, far touchline at top, near touchline at bottom. Choose an anonymous participant."><svg viewBox="0 0 50 100" preserveAspectRatio="none" aria-hidden="true"><path d="M0 0H50V100H0Z M0 20H16V80H0 M0 39H6V61H0 M0 44H-1V56H0 M50 35A15 15 0 0 0 50 65"/></svg>${reconstruction?reconstruction.participants.map(p=>`<span id="pl-uncertainty-${p.id}" class="pl-uncertainty ${p.team}" hidden aria-hidden="true"></span><button id="pl-track-${p.id}" class="pl-track ${p.team}" data-pl-participant="${p.id}" aria-pressed="false" hidden><span>${p.shirt??'GK'}</span></button>`).join(''):''}<p id="pl-reconstruction-empty" hidden>Positions unknown<br><small>Outside the supported passage</small></p></div></div><div class="pl-marker-legend"><span><i class="pl-solid-key" aria-hidden="true"></i> Solid: reviewed-frame estimate</span><span><i class="pl-hollow-key" aria-hidden="true"></i> Hollow: interpolated estimate</span><span>Broad shaded area: schematic uncertainty</span></div><p class="pl-reconstruction-limit">3-second sampled passage · two anonymous participants · ball and other players unknown</p><p id="pl-interpolation" class="pl-readout"></p></section><label class="pl-player-label" for="pl-player"><span id="pl-player-caption">Source-joined identity</span> <select id="pl-player">${model.identities.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · Brentford ${p.shirt}</option>`).join('')}</select></label><p id="pl-position" class="pl-readout"></p><div id="pl-transport"><div class="pl-clocks"><div><span>Clip cursor</span><strong id="pl-clip"></strong></div><div><span>Captured match clock</span><strong id="pl-match-clock"></strong></div><div><span>Captured scoreboard</span><strong id="pl-score"></strong></div></div><p id="pl-capture" class="pl-readout"></p><label class="sr-only" for="pl-range">Clip cursor, including unreviewed gaps</label><input id="pl-range" type="range" min="${model.start}" max="${model.end}" step="0.01" value="${model.start}"><div class="pl-controls"><button id="pl-play" aria-pressed="false">▶ Play captures</button><button id="pl-previous">← Previous capture</button><button id="pl-next">Next capture →</button><button id="pl-gap">Inspect gap</button></div><p id="pl-stepping" class="pl-stepping">One step = one reviewed capture, every 0.9 seconds. This is not match-speed playback or continuous video.</p><p id="pl-announcement" role="status" aria-live="polite"></p></div><section class="pl-observations" aria-labelledby="pl-observations-heading"><h2 id="pl-observations-heading">Observed by this cursor</h2><p id="pl-observations-empty">No reviewed observations are eligible here.</p><ol id="pl-facts"></ol></section></section><section class="conversation pl-conversation" aria-label="Local questions about recorded annotations"><div class="conversation-bar"><div><span class="avatar" aria-hidden="true">↗</span><div><strong id="pl-speaker">The recorded observations</strong><small>Local grounded answers · No AI</small></div></div></div><p id="pl-question-intro" class="pl-question-intro">Inspect a capture or gap, choose a source-joined player, then ask what the evidence supports.</p><div id="pl-thread" role="log" aria-live="polite" aria-label="Cursor-bound answers"></div><div id="pl-suggestions">${questions.map(q=>`<button data-pl-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="pl-composer"><label for="pl-draft" class="sr-only">Question about these annotations</label><input id="pl-draft" autocomplete="off" placeholder="Ask about the reviewed evidence…"><button type="submit" aria-label="Send question">↑</button></form><p id="pl-status" role="status">Answers stay bound to the clip cursor and selected player.</p><p class="pl-question-footer">Sampled manual observations · Estimates and unknowns stay explicit</p></section>`;
if(hasTimeline){node('modes').hidden=false;node('modes').insertAdjacentHTML('afterbegin','<button id="pl-mode-timeline" aria-pressed="true">Match timeline</button>');panel.insertAdjacentHTML('beforeend','<section id="pl-timeline-panel" class="pl-timeline-panel" aria-label="Full-match timeline workspace"></section>');}
const timeline=hasTimeline?root.PLTimeline.mount(node('timeline-panel')):null;
if(hasGoal){node('modes').hidden=false;node('modes').insertAdjacentHTML('afterbegin','<button id="pl-mode-goal" aria-pressed="true">First goal · On the pitch</button>');panel.insertAdjacentHTML('beforeend','<section id="pl-goal-panel" class="pl-goal-panel" aria-label="First-goal pitch passage"></section>');}
const goal=hasGoal?root.PLGoalPitch.mount(node('goal-panel'),hasOfficial?{onOfficial:()=>{changeMode('official');official.focusHeading();}}:{}):null;
if(hasOfficial){node('modes').hidden=false;node('modes').insertAdjacentHTML('beforeend','<button id="pl-mode-official" aria-pressed="false">Official match record</button>');panel.insertAdjacentHTML('beforeend','<section id="pl-official-panel" class="pl-official-panel" aria-label="Completed official match record"></section>');}
if(hasPassage){node('modes').hidden=false;node('modes').insertAdjacentHTML('beforeend','<button id="pl-mode-passage" aria-pressed="false">Longer passage · On the pitch</button>');panel.insertAdjacentHTML('beforeend','<section id="pl-passage-panel" class="pl-passage-panel" aria-label="Longer estimated video passage"></section>');}
const passage=hasPassage?root.PLPassageView.mount(node('passage-panel')):null;
const official=hasOfficial?root.PLOfficialView.mount(node('official-panel'),{onExplore:()=>{changeMode('goal');goal?.showPassage();},onReturn:()=>{changeMode('goal');goal?.focusRecordAction();}}):null;
if(hasReconstructed){node('modes').hidden=false;node('modes').insertAdjacentHTML('afterbegin','<button id="pl-mode-reconstructed" aria-pressed="true">Reconstructed replay</button>');panel.insertAdjacentHTML('beforeend','<section id="pl-reconstructed-panel" class="pl-reconstructed-panel" aria-label="Generated whole-match reconstruction"></section>');}
const whole=hasReconstructed?root.PLReconstructedView.mount(node('reconstructed-panel'),{onEvidence:target=>changeMode(target)}):null;
const reviewedContext=MatchWorkspace.context({state:'RECORDED ANNOTATIONS',title:'16 reviewed captures · approximately 23 clip seconds',subtitle:'Two source-joined identities, not a full XI · No continuous tracking',sources:'<details class="pl-sources"><summary class="text-button">Sources & limits ↗</summary><p>Manual review of 16 paused source captures. Clip timestamps and displayed second-precision match clocks are separate; there is no universal clock fit. Source footage and screenshots are not loaded in this preview.</p><p>Positions are coarse landmark regions only at exact reviewed points. No x/y, metres, calibrated pitch side, player dots, ball positions, speed, trails or interpolation. All intervals between captures and camera changes contain unreviewed movement.</p><p>Earlier report claims are separate retrospective research. Scorer, assist, finish and exact contact/goal times are not timed facts in this view. A captured score change is not the goal time. Eligibility is a retrospective display policy, not live arrival or known-then evidence.</p><p><a href="'+esc(bundle.source.url)+'" target="_blank" rel="noopener">Official full recording ↗</a> · Opens source material beyond this bounded preview.</p><details><summary>Static source receipts</summary><pre tabindex="0">'+esc(JSON.stringify({artifact:bundle.source.artifact,captureReceipt:bundle.source.captureReceipt,captureHashManifest:bundle.source.captureHashManifest},null,2))+'</pre></details><p>No media download, provider connection or new source acquisition. Source-use and submission limits remain separate.</p></details>'});
function configureMode(){
 const isEstimate=estimated();
 const isTimeline=mode==='timeline';
 const isGoal=mode==='goal';
 const isOfficial=mode==='official';
 const isPassage=mode==='passage';
 const isReconstructed=mode==='reconstructed';
 if(whole){node('mode-reconstructed').setAttribute('aria-pressed',String(isReconstructed));node('reconstructed-panel').hidden=!isReconstructed;if(isReconstructed&&opened)whole.activate();else whole.deactivate();}
 if(passage){node('mode-passage').setAttribute('aria-pressed',String(isPassage));node('passage-panel').hidden=!isPassage;if(isPassage&&opened)passage.activate();else passage.deactivate();}
 if(official){node('mode-official').setAttribute('aria-pressed',String(isOfficial));node('official-panel').hidden=!isOfficial;if(isOfficial&&opened)official.activate();else official.deactivate();}
 if(goal){node('mode-goal').setAttribute('aria-pressed',String(isGoal));node('goal-panel').hidden=!isGoal;if(isGoal&&opened)goal.activate();else goal.deactivate();}
 if(timeline){node('mode-timeline').setAttribute('aria-pressed',String(isTimeline));node('timeline-panel').hidden=!isTimeline;node('inspector').hidden=isTimeline;panel.querySelector('.pl-conversation').hidden=isTimeline;if(isTimeline&&opened)timeline.activate();else timeline.deactivate();}
 node('mode-estimated').setAttribute('aria-pressed',String(isEstimate));node('mode-reviewed').setAttribute('aria-pressed',String(mode==='reviewed'));
 node('inspector').hidden=isTimeline||isGoal||isOfficial||isPassage||isReconstructed;panel.querySelector('.pl-conversation').hidden=isTimeline||isGoal||isOfficial||isPassage||isReconstructed;
 if(isTimeline||isGoal||isOfficial||isPassage||isReconstructed)return;
 node('reviewed-map').hidden=isEstimate;node('estimated-map').hidden=!isEstimate;
 if(node('inspector').insertBefore)node('inspector').insertBefore(node('transport'),isEstimate?node('estimated-map'):node('observations'));
 text(node('question-intro'),isEstimate?'Inspect a reviewed frame or interpolated estimate, choose an anonymous participant, then ask what the evidence supports.':'Inspect a capture or gap, choose a source-joined player, then ask what the evidence supports.');
 text(node('speaker'),isEstimate?'The estimated passage':'The recorded observations');
 text(node('observations-empty'),isEstimate?'No reconstruction evidence supports a position at this cursor.':'No reviewed observations are eligible here.');
 text(node('player-caption'),isEstimate?'Anonymous participant':'Source-joined identity');
 node('player').innerHTML=participants().map(p=>`<option value="${esc(p.id)}">${esc(p.label||p.name+(p.team==='brentford'?' · Brentford '+p.shirt:''))}</option>`).join('');
 node('range').min=String(active().start);node('range').max=String(isEstimate?reconstruction.inspectEnd:model.end);
 node('suggestions').innerHTML=(isEstimate?questions.filter(q=>q!=='What does the scoreboard show?'):questions).map(q=>`<button data-pl-question="${esc(q)}">${esc(q)}</button>`).join('');
 text(node('observations-heading'),isEstimate?'Evidence at this cursor':'Observed by this cursor');
 text(node('previous'),isEstimate?'← Previous frame':'← Previous capture');text(node('next'),isEstimate?'Next frame →':'Next capture →');
 node('context').innerHTML=isEstimate?MatchWorkspace.context({state:'VIDEO RECONSTRUCTION',title:'Video reconstruction · Estimated positions',subtitle:'Seven sampled frames · Not measured tracking or a live feed',sources:'<details class="pl-sources"><summary class="text-button">Sources, method & unknowns ↗</summary><p>Seven paused frames from one wide camera view, clip 01:01:55–01:01:58. This is sampled evidence, not continuous or frame-complete review. Solid markers are broad manual layout estimates at reviewed frames; hollow markers interpolate between adjacent frames.</p><p>Interpolation uses the neighbouring future reviewed endpoint. This is retrospective reconstruction, not known-then evidence or an observed running path. No clock, scoreboard, contact or event is inferred between frames.</p><p>Normalized schematic layout only: goal at left, far touchline at top, near touchline at bottom. The attacking half and broad uncertainty areas are illustrative, not calibrated coordinates, metres or statistical confidence. Perspective, crowding and occlusion limit placement.</p><p>Only anonymous Brentford shirt 27 and the sole green Chelsea goalkeeper are represented. Their names, the ball, other players, contacts, scorer action, outcome, tactics and movement metrics remain unknown. No positions carry outside the three-second passage or through a camera cut.</p><p>DOM clip timestamps and burned-in second-precision clocks stay separate. The source player’s transport label was stale and is not used for capture timing. Screenshots and source footage are not loaded here.</p><p><a href="'+esc(bundle.source.url)+'" target="_blank" rel="noopener">Official full recording ↗</a> · Opens material beyond this bounded preview.</p><details><summary>Static source receipts</summary><pre tabindex="0">'+esc(JSON.stringify(root.PLReconstructionSample.source,null,2))+'</pre></details><p>Original annotation evidence remains separate. Source-use, submission and publication limits remain unresolved separately.</p></details>'}):reviewedContext;
 text(node('stepping'),isEstimate?'Play advances the clip cursor at 1× elapsed time across three seconds. Step buttons reach the seven reviewed frames; Inspect gap goes beyond supported positions.':'One step = one reviewed capture, every 0.9 seconds. This is not match-speed playback or continuous video.');
 factKey='';
}
function stop(){generation++;if(timer!==null)clearInterval(timer);timer=null;text(node('play'),estimated()?'▶ Play estimated replay':'▶ Play captures');node('play').setAttribute('aria-pressed','false');text(node('announcement'),'Paused at clip '+model.formatClip(cursor)+'.');}
function clear(){node('thread').replaceChildren();text(node('status'),'New answers use the current clip cursor and selected player.');}
function paint(){
 if(mode==='timeline'||mode==='goal'||mode==='official'||mode==='passage'||mode==='reconstructed')return;
 if(estimated()){paintEstimated();return;}
 const view=model.view(cursor,selected),player=model.identities.find(p=>p.id===selected);
 node('range').value=String(cursor);node('range').setAttribute('aria-valuetext',`Clip ${model.formatClip(cursor)}. ${view.point?'Reviewed capture '+view.point.id+', broadcast clock '+view.point.clock:'Unreviewed gap; match clock and positions unknown'}.`);
 node('player').value=selected;text(node('clip'),model.formatClip(cursor));text(node('match-clock'),view.point?view.point.clock:'Unknown · gap');text(node('score'),view.point?view.point.score.join('–'):'Unknown · gap');
 text(node('capture'),view.point?`Capture ${view.point.id} · displayed match clock ${view.point.clock}, second precision. Captured scoreboard only; no exact goal time.`:'Unreviewed gap. Captured match clock, scoreboard and all positions are unknown here. Earlier eligible observations remain below.');
 text(node('position'),view.position?`${player.name}: ${view.position.text}. Coarse visible estimate at ${view.position.evidenceId}; side and exact location unknown.`:`${player.name}: position unknown. ${view.point?'This capture has no supported coarse region for this player.':'No reviewed capture at this exact cursor; no position is held or interpolated.'}`);
 for(const [id,zone] of [['goalmouth','near_goalmouth_cluster'],['corner','corner_boundary']])node(id).dataset.active=String(view.position?.zone===zone);
 node('diagram').setAttribute('aria-label',view.position?'Schematic region: '+view.position.text+'. Side and exact location unknown.':'No supported coarse position. Both schematic regions are inactive.');
 const key=view.observations.map(o=>o.id).join('|');if(key!==factKey){node('facts').innerHTML=view.observations.map(o=>`<li><span>Clip ${esc(model.formatClip(o.availableAt))} · ${esc(o.evidenceIds.join(', '))}</span><p>${esc(o.text)}</p></li>`).join('');factKey=key;}
 node('observations-empty').hidden=view.observations.length>0;
 node('previous').disabled=model.adjacent(cursor,-1)===null;node('next').disabled=model.adjacent(cursor,1)===null;node('gap').disabled=model.gap(cursor)===null;node('play').disabled=cursor>=model.end;
}
function paintEstimated(){
 const view=reconstruction.view(cursor,selected),p=view.position,actor=reconstruction.participants.find(p=>p.id===selected);
 node('range').value=String(cursor);node('range').setAttribute('aria-valuetext',`Clip ${model.formatClip(cursor)}. ${view.frame?'Reviewed frame '+view.frame.id+', broadcast clock '+view.frame.clock:p?'Interpolated estimate; captured clock and scoreboard unknown':'Outside support; positions, clock and scoreboard unknown'}.`);
 node('player').value=selected;text(node('clip'),model.formatClip(cursor));text(node('match-clock'),view.frame?view.frame.clock:'Unknown · no frame');text(node('score'),view.frame?view.frame.score.join('–'):'Unknown · no frame');
 text(node('capture'),view.frame?`Reviewed frame ${view.frame.id} · captured display ${view.frame.clock}. Scoreboard only, not an event or goal time.`:'No reviewed frame at this exact cursor. Captured match clock and scoreboard are unknown.');
 text(node('position'),actor.label+': '+(p?(actor.id==='shirt27'?'near the near-side penalty-area edge':'near the goalmouth')+' · broad schematic estimate.':'position unknown. No positions are carried outside the supported segment.'));
 text(node('interpolation'),p?p.disclosure+(p.usesFutureEndpoint?' Uses '+p.evidenceIds.join(' and ')+'; the second frame is after this cursor.':' Evidence '+p.evidenceIds[0]+'.'):'Outside the three-second support. Both participant markers are hidden; ball and other players remain unknown.');
 for(const participant of reconstruction.participants){const value=reconstruction.view(cursor,participant.id).position,marker=node('track-'+participant.id),region=node('uncertainty-'+participant.id);marker.hidden=region.hidden=!value;marker.setAttribute('aria-pressed',String(selected===participant.id));if(value){marker.dataset.kind=value.kind;marker.style.left=(value.x*2)+'%';marker.style.top=value.y+'%';region.style.left=(value.x*2)+'%';region.style.top=value.y+'%';region.style.width=(value.radius*4)+'%';region.style.height=(value.radius*2)+'%';marker.setAttribute('aria-label','Select '+participant.label+'. '+value.disclosure+' Evidence '+value.evidenceIds.join(' / ')+'.');}}
 node('reconstruction-empty').hidden=!!p;
 const key=(p?p.evidenceIds.join('|'):'unknown')+':'+(p?.kind||'');if(key!==factKey){node('facts').innerHTML=p?`<li><span>${esc(p.evidenceIds.join(' / '))} · ${p.usesFutureEndpoint?'Neighbouring reviewed frames':'Reviewed frame'}</span><p>${esc(p.disclosure)} ${p.usesFutureEndpoint?'The future endpoint supplies layout interpolation only.':''}</p></li>`:'';factKey=key;}
 node('observations-empty').hidden=!!p;text(node('observations-empty'),'No reconstruction evidence supports a position at this cursor.');
 node('previous').disabled=reconstruction.adjacent(cursor,-1)===null;node('next').disabled=reconstruction.adjacent(cursor,1)===null;node('gap').disabled=cursor>reconstruction.end;node('play').disabled=cursor>=reconstruction.end;
}
function seek(time){stop();cursor=active().clamp(time);clear();paint();text(node('announcement'),'Paused at clip '+model.formatClip(cursor)+(estimated()?'. '+(reconstruction.view(cursor,selected).frame?'Reviewed-frame estimate.':reconstruction.view(cursor,selected).position?'Interpolated estimate.':'Outside supported positions.'):(model.view(cursor,selected).point?'. Reviewed capture.':'. Unreviewed gap.')));}
function select(id){const p=participants().find(p=>p.id===id);if(!p)return;stop();selected=id;clear();paint();text(node('announcement'),(p.label||p.name)+' selected.');}
function changeMode(value){if(value===mode||(!['goal','official','timeline','estimated','reviewed','reconstructed'].includes(value)&&value!=='passage')||(value==='reconstructed'&&!whole)||(value==='passage'&&!passage)||(value==='official'&&!official)||(value==='goal'&&!goal)||(value==='timeline'&&!timeline)||(value==='estimated'&&!reconstruction))return;stop();if(!['timeline','goal','official','passage','reconstructed'].includes(mode))states[mode]={cursor,selected};mode=value;if(!['timeline','goal','official','passage','reconstructed'].includes(mode))({cursor,selected}=states[mode]);clear();configureMode();stop();paint();text(node('announcement'),mode==='reconstructed'?'Generated whole-match reconstruction selected. Movement is illustrative.':mode==='passage'?'Longer estimated video passage selected.':mode==='official'?'Completed official match reference selected. Includes later events and final statistics.':mode==='goal'?'First-goal pitch passage selected.':mode==='timeline'?'Match timeline selected. Completed evidence passages.':estimated()?'Estimated replay selected. Retrospective manual reconstruction.':'Reviewed captures selected. Exact-point coarse regions.');}
function run(){
 stop();if(cursor>=active().end)return;clear();const token=generation;
 if(estimated()){const origin=cursor,started=now();timer=setInterval(()=>{if(token!==generation)return;cursor=Math.min(reconstruction.end,origin+(now()-started)/1000);paint();if(cursor===reconstruction.end){stop();text(node('announcement'),'End of the three-second estimated passage. Playback stopped.');}},16);}
 else timer=setInterval(()=>{if(token!==generation)return;const next=model.adjacent(cursor,1);if(next===null){stop();return;}cursor=next;clear();paint();text(node('announcement'),'Reviewed capture at clip '+model.formatClip(cursor)+'.');if(cursor===model.end){stop();text(node('announcement'),'End of the reviewed captures. Playback stopped.');}},900);
 text(node('announcement'),estimated()?'Playing estimated passage at 1×. Interpolated positions use neighbouring reviewed frames.':'Playing reviewed captures, one step every 0.9 seconds.');
 text(node('play'),estimated()?'Ⅱ Pause estimated replay':'Ⅱ Pause captures');node('play').setAttribute('aria-pressed','true');
}
function ask(question){if(!String(question).trim())return;stop();const answer=active().answer(cursor,selected,question),player=participants().find(p=>p.id===selected),view=active().view(cursor,selected),point=estimated()?view.frame:view.point,name=player.label||player.name,stamp=`${estimated()?'ESTIMATED REPLAY':'REVIEWED CAPTURES'} · CLIP ${model.formatClip(cursor)} · ${name}${point?' · '+(estimated()?'FRAME ':'CAPTURE ')+point.id+' / MATCH '+point.clock:' · MATCH CLOCK UNKNOWN'}`;node('thread').insertAdjacentHTML('beforeend',MatchWorkspace.message(question,true,stamp,'')+MatchWorkspace.message(answer.text,false,stamp,(estimated()?'Manual reconstruction estimates':'Local source observations')+' · no AI'+(answer.evidenceIds.length?' · '+answer.evidenceIds.join(', '):'')));text(node('status'),'Answer at clip '+model.formatClip(cursor)+' · '+name+'.');}
function open(back){stop();clear();opened=true;onBack=back;panel.hidden=false;if(mode==='timeline')timeline.activate();if(mode==='goal')goal.activate();if(mode==='official')official.activate();if(mode==='passage')passage.activate();if(mode==='reconstructed')whole.activate();paint();node('title').focus({preventScroll:true});}
function close(){stop();clear();timeline?.deactivate();goal?.deactivate();official?.deactivate();passage?.deactivate();whole?.deactivate();opened=false;panel.hidden=true;const back=onBack;onBack=null;if(back)back();}
node('range').addEventListener('input',e=>seek(Number(e.target.value)));
node('player').addEventListener('change',e=>select(e.target.value));
node('composer').addEventListener('submit',e=>{e.preventDefault();ask(node('draft').value);node('draft').value='';});
panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='pl-back')close();else if(b.id==='pl-mode-reconstructed')changeMode('reconstructed');else if(b.id==='pl-mode-passage')changeMode('passage');else if(b.id==='pl-mode-official')changeMode('official');else if(b.id==='pl-mode-goal')changeMode('goal');else if(b.id==='pl-mode-timeline')changeMode('timeline');else if(b.id==='pl-mode-estimated'||b.id==='pl-mode-reviewed')changeMode(b.id==='pl-mode-estimated'?'estimated':'reviewed');else if(mode==='timeline'||mode==='goal'||mode==='official'||mode==='passage'||mode==='reconstructed')return;else if(b.dataset.plParticipant)select(b.dataset.plParticipant);else if(b.dataset.plQuestion)ask(b.dataset.plQuestion);else if(b.id==='pl-play'){if(timer!==null){stop();clear();}else run();}else if(b.id==='pl-previous'||b.id==='pl-next'){const time=active().adjacent(cursor,b.id==='pl-previous'?-1:1);if(time!==null)seek(time);}else if(b.id==='pl-gap'){const time=active().gap(cursor);if(time!==null)seek(time);}});
function stopAll(){stop();clear();timeline?.stop();goal?.stop();official?.stop();passage?.stop();whole?.stop();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAll();});root.addEventListener('pagehide',stopAll);document.addEventListener('matchmate:workspace-exit',stopAll);
root.PLAnnotations={open,close,stop:stopAll,isOpen:()=>opened};configureMode();stop();paint();
})(window);
